// Normalization transforms this:
const arrayResponse = [{ id: '1', name: 'A' }, { id: '2', name: 'B' }];

// Into this:
const normalizedState = {
  ids: ['1', '2'],
  entities: {
    '1': { id: '1', name: 'A' },
    '2': { id: '2', name: 'B' }
  }
};

// Updating is now O(1) instant, instead of O(N) array searching!
function updateName(state, id, newName) {
  state.entities[id].name = newName;
}
